const keys=['font','fontSize','fontWeight','color','italic','underline','strikethrough','tracking','baselineShift','horizontalScale','verticalScale','kerning','autoKerning'],limits={fontSize:[1,2048],fontWeight:[100,900],tracking:[-100,500],baselineShift:[-2048,2048],horizontalScale:[10,500],verticalScale:[10,500],kerning:[-100,500]},clone=x=>JSON.parse(JSON.stringify(x));
export function validateTextStyle(s){if(!s||typeof s!=='object'||Array.isArray(s))throw Error('Invalid text style.');for(const[k,v]of Object.entries(s)){if(!keys.includes(k))throw Error('Unknown text style.');if(limits[k]&&(!Number.isFinite(v)||v<limits[k][0]||v>limits[k][1]))throw Error('Invalid type metric.');if(['italic','underline','strikethrough','autoKerning'].includes(k)&&typeof v!=='boolean')throw Error('Invalid type flag.');if(k==='font'&&(typeof v!=='string'||!/^[a-z0-9 _-]{1,80}$/i.test(v)))throw Error('Invalid font.');if(k==='color'&&!/^#[0-9a-f]{3}(?:[0-9a-f]{3})?$/i.test(v))throw Error('Invalid color.');}}
export function validateText(l){validateTextStyle(Object.fromEntries(keys.filter(k=>l[k]!==undefined).map(k=>[k,l[k]])));for(const k of ['firstLineIndent','startIndent','endIndent','spaceBefore','spaceAfter'])if(l[k]!==undefined&&(!Number.isFinite(l[k])||Math.abs(l[k])>10000))throw Error('Invalid paragraph metric.');if(l.align&&!['left','center','right','justify'].includes(l.align))throw Error('Invalid alignment.');if(l.textRuns){if(!Array.isArray(l.textRuns)||l.textRuns.length>512)throw Error('Invalid text ranges.');let end=0;for(const r of l.textRuns){if(!Number.isInteger(r.from)||!Number.isInteger(r.to)||r.from<end||r.to<=r.from||r.to>l.text.length)throw Error('Invalid text range.');validateTextStyle(r.style);end=r.to;}}}
export function advancedText(l){return !!(l.textRuns?.length||l.strikethrough||l.baselineShift||l.kerning||l.horizontalScale&&l.horizontalScale!==100||l.verticalScale&&l.verticalScale!==100||l.autoKerning===false||l.firstLineIndent||l.startIndent||l.endIndent||l.spaceBefore||l.spaceAfter||l.align==='justify');}
function styles(l){const a=Array(l.text.length).fill(null);for(const r of l.textRuns||[])for(let i=r.from;i<r.to;i++)a[i]=r.style;return a;}
function ranges(a){const out=[];for(let i=0;i<a.length;){const k=JSON.stringify(a[i]||{});let end=i+1;while(end<a.length&&JSON.stringify(a[end]||{})===k)end++;if(a[i]&&Object.keys(a[i]).length)out.push({from:i,to:end,style:clone(a[i])});i=end;}if(out.length>512)throw Error('Tối đa512 đoạn kiểu.');return out;}
export function applyTextStyle(l,from,to,s){validateTextStyle(s);from=Math.max(0,Math.min(l.text.length,Math.floor(from)));to=Math.max(from,Math.min(l.text.length,Math.floor(to)));if(from===to)throw Error('Chọn ít nhất một ký tự.');const a=styles(l);for(let i=from;i<to;i++)a[i]={...a[i],...s};l.textRuns=ranges(a);}
export function clearTextStyle(l,from=0,to=l.text.length){const a=styles(l);for(let i=Math.max(0,from);i<Math.min(a.length,to);i++)a[i]=null;l.textRuns=ranges(a);}
export function editText(l,next){next=next.slice(0,10000);if(next===l.text)return;const old=l.text,a=styles(l);let f=0,b=0;while(f<old.length&&f<next.length&&old[f]===next[f])f++;while(b<old.length-f&&b<next.length-f&&old[old.length-1-b]===next[next.length-1-b])b++;const inherit=a[Math.max(0,f-1)]||a[f]||null;l.textRuns=ranges([...a.slice(0,f),...Array(next.length-f-b).fill(inherit),...a.slice(old.length-b)]);l.text=next;}
export function scaleText(l,sx,sy=sx){const c=(v,a,b)=>Math.max(a,Math.min(b,v));for(const s of [l,...(l.textRuns||[]).map(r=>r.style)]){if(s.fontSize!==undefined)s.fontSize=c(s.fontSize*Math.min(sx,sy),1,2048);for(const k of ['tracking','kerning'])if(s[k]!==undefined)s[k]=c(s[k]*sx,-100,500);if(s.baselineShift!==undefined)s.baselineShift=c(s.baselineShift*sy,-2048,2048);}for(const k of ['startIndent','endIndent','firstLineIndent'])if(l[k]!==undefined)l[k]=c(l[k]*sx,-10000,10000);for(const k of ['spaceBefore','spaceAfter'])if(l[k]!==undefined)l[k]=c(l[k]*sy,-10000,10000);}
export const fontString=s=>`${s.italic?'italic ':''}${s.fontWeight||400} ${s.fontSize||48}px "${s.font||'Arial'}"`;
function segment(s){if(typeof Intl.Segmenter==='function')return [...new Intl.Segmenter(undefined,{granularity:'grapheme'}).segment(s)].map(p=>({text:p.segment,index:p.index}));let index=0;return Array.from(s).map(text=>{const r={text,index};index+=text.length;return r;});}
export function layoutText(ctx,l){const map=styles(l),lines=[];let offset=0,y=0;for(const paragraph of l.text.split('\n')){y+=l.spaceBefore||0;let first=true,line=[],width=0;const left=()=>Number(l.startIndent||0)+(first?Number(l.firstLineIndent||0):0),available=()=>Math.max(1,l.width-left()-Number(l.endIndent||0));const finish=last=>{while(line.length&&/^\s+$/.test(line.at(-1).text))width-=line.pop().advance;const height=Math.max(l.fontSize||48,...line.map(g=>(g.style.fontSize||48)*(g.style.verticalScale??100)/100))*(l.lineHeight||1.2),spaces=line.filter(g=>g.text===' ').length,extra=l.align==='justify'&&!last&&spaces?Math.max(0,available()-width)/spaces:0;let x=left()+(l.align==='center'?(available()-width)/2:l.align==='right'?available()-width:0);for(const g of line){g.x=x;g.y=y-(g.style.baselineShift||0);x+=g.advance+(g.text===' '?extra:0);}lines.push({glyphs:line,y,height,width,last});y+=height;first=false;line=[];width=0;};let pos=0;for(const token of paragraph.match(/\s+|\S+/gu)||[]){const gs=segment(token).map(g=>{const style={...l,...map[offset+pos+g.index]},font=fontString(style);ctx.font=font;return{...g,style,font,advance:ctx.measureText(g.text).width*(style.horizontalScale??100)/100+(style.tracking||0)+(style.kerning||0)};});pos+=token.length;if(!/^\s+$/.test(token)&&line.length&&width+gs.reduce((n,g)=>n+g.advance,0)>available())finish(false);for(const g of gs){if(!line.length&&/^\s+$/.test(g.text))continue;if(line.length&&width+g.advance>available())finish(false);const p=line.at(-1);if(p&&p.font===g.font&&g.style.autoKerning!==false){ctx.font=g.font;const k=(ctx.measureText(p.text+g.text).width-ctx.measureText(p.text).width-ctx.measureText(g.text).width)*(p.style.horizontalScale??100)/100;p.advance+=k;width+=k;}line.push(g);width+=g.advance;}}finish(true);y+=l.spaceAfter||0;offset+=paragraph.length+1;}return{lines,height:y};}
export function paintText(ctx,l){const result=layoutText(ctx,l);for(const line of result.lines)for(const g of line.glyphs){const s=g.style,sx=(s.horizontalScale??100)/100;ctx.save();ctx.translate(g.x,g.y);ctx.scale(sx,(s.verticalScale??100)/100);ctx.font=g.font;ctx.textBaseline='top';ctx.textAlign='left';ctx.fillStyle=s.color||'#fff';ctx.fillText(g.text,0,0);if(s.underline)ctx.fillRect(0,s.fontSize*1.01,Math.max(0,g.advance/sx),Math.max(1,s.fontSize/18));if(s.strikethrough)ctx.fillRect(0,s.fontSize*.48,Math.max(0,g.advance/sx),Math.max(1,s.fontSize/20));ctx.restore();}return result;}
